/* Langues de l'appli : français (référence), anglais, italien, espagnol, allemand.
   Les clés du dictionnaire sont les textes français d'origine : un texte sans traduction reste affiché en français.
   K('texte français','English','Italiano','Español','Deutsch'). Les valeurs enregistrées (catégories, états, couleurs…) ne changent jamais :
   seul leur affichage passe par tv(). */
(function(){
const LANGS=[['fr','Français'],['en','English'],['it','Italiano'],['es','Español'],['de','Deutsch']];
const LOCS={fr:'fr-FR',en:'en-GB',it:'it-IT',es:'es-ES',de:'de-DE'};
const D={en:{},it:{},es:{},de:{}};
const I18N=window.I18N={LANGS,LOCS,D,lang:'fr',miss:new Set()};
window.K=(fr,en,it,es,de)=>{D.en[fr]=en;D.it[fr]=it;D.es[fr]=es;D.de[fr]=de};

/* langue choisie dans les réglages, sinon celle du navigateur, sinon le français */
window.detectLang=()=>{
 try{const c=JSON.parse(localStorage.getItem('cfg')||'{}');if(c&&LOCS[c.lang])return c.lang}catch(e){}
 const l=(navigator.languages&&navigator.languages.length?navigator.languages:[navigator.language||'fr']);
 for(const x of l){const k=String(x).slice(0,2).toLowerCase();if(LOCS[k])return k}
 return 'en'};

const fill=(s,v)=>v?s.replace(/\{(\w+)\}/g,(m,n)=>v[n]!=null?v[n]:m):s;
window.t=(k,v)=>{let s=k;if(I18N.lang!=='fr'){const d=D[I18N.lang][k];if(d!=null)s=d;else if(k&&/[a-zà-ÿ]/i.test(k))I18N.miss.add(k)}return fill(s,v)};
/* valeur enregistrée (catégorie, couleur, état…) : traduite à l'affichage, jamais modifiée dans les données */
window.tv=v=>{if(v==null||v===''||I18N.lang==='fr')return v;const d=D[I18N.lang][v];return d!=null?d:v};
/* pluriel : « 2 ventes » ; en français 0 et 1 sont au singulier */
window.tn=(n,sg,pl)=>n+' '+t((I18N.lang==='fr'?n>1:n!==1)?pl:sg);

/* pays « Made in » : les noms viennent de la liste française de l'appli (MADEIN0), l'affichage vient d'Intl.DisplayNames */
const nk=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const ALIAS={'birmanie':'MM','bielorussie':'BY','vatican':'VA','cap vert':'CV','eswatini':'SZ','timor oriental':'TL','macedoine du nord':'MK','uk':'GB','usa':'US','taiwan':'TW','congo':'CG','salomon':'SB','palaos':'PW','groenland':'GL','porto rico':'PR','hong kong':'HK','macao':'MO','palestine':'PS','kosovo':'XK'};
let cnMap=null,cnLang='',cnRev=null,cnDN=null;
function cnBuild(){
 if(cnMap)return;cnMap={};const fr=new Intl.DisplayNames(['fr'],{type:'region'}),byFr={};
 for(let a=65;a<=90;a++)for(let b=65;b<=90;b++){const c=String.fromCharCode(a,b);try{const n=fr.of(c);if(n&&n!==c)byFr[nk(n)]=c}catch(e){}}
 const names=(typeof MADEIN0!=='undefined'?MADEIN0:[]);
 names.forEach(n=>{const k=nk(n),c=ALIAS[k]||byFr[k];if(c)cnMap[n]=c});
 /* quelques noms de l'appli diffèrent de ceux d'Intl */
 names.forEach(n=>{if(!cnMap[n]){const k=nk(n),c=Object.keys(byFr).find(x=>x.indexOf(k)>=0||k.indexOf(x)>=0);if(c)cnMap[n]=byFr[c]}})}
window.cn=v=>{if(!v||I18N.lang==='fr')return v;cnBuild();const c=cnMap[v];if(!c)return v;try{if(cnLang!==I18N.lang){cnDN=new Intl.DisplayNames([LOCS[I18N.lang]],{type:'region'});cnLang=I18N.lang;cnRev=null}return cnDN.of(c)||v}catch(e){return v}};
/* nom saisi ou choisi dans la langue de l'écran → nom français enregistré (ou saisie libre inchangée) */
window.cnFr=v=>{v=String(v||'').trim();if(!v||I18N.lang==='fr')return v;cnBuild();cn('x');if(!cnRev){cnRev={};Object.keys(cnMap).forEach(n=>{const k=nk(cn(n));if(!cnRev[k])cnRev[k]=n})}return cnRev[nk(v)]||v};
})();

